function t(e){if(!e)return"—";const n=new Date(e);if(Number.isNaN(n.getTime()))return String(e);const s=i=>String(i).padStart(2,"0");return`${n.getFullYear()}-${s(n.getMonth()+1)}-${s(n.getDate())} ${s(n.getHours())}:${s(n.getMinutes())}`}function r(e){return{deployed:"success",success:"success",issued:"success",active:"success",skipped:"info",draft:"info",idle:"info",pending:"warning",running:"warning",issuing:"warning",failed:"danger",disabled:"info"}[e]||"info"}function a(e){return{deployed:"已部署",issued:"已签发",draft:"草稿",issuing:"签发中",failed:"失败",success:"成功",skipped:"已跳过",pending:"等待",running:"执行中",idle:"空闲",active:"启用",disabled:"停用",triggered:"已触发"}[e]||e||"—"}export{a,t as f,r as s};
